// argparse.mjs — manual re-implementation of the exact subset of CPython 3.12
// argparse used by test2: one required string option `--a` plus the automatic
// `-h/--help`. Pure Node ESM: no imports, no JSON, no RegExp.
//
// Mirrors argparse semantics: `--a value`, `--a=value`, unambiguous long-option
// abbreviations, repeated option (last wins), the `--` separator, the
// negative-number heuristic for option-looking values, deferred
// "unrecognized arguments" errors, and CPython's exact usage/help text.

const LONG_OPTIONS = ['--help', '--a'];

function isDigits(text) {
  if (text.length === 0) return false;
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i);
    if (code < 48 || code > 57) return false;
  }
  return true;
}

// Mirrors argparse._negative_number_matcher = re.compile(r'-\d+$|-\d*\.\d+$').
function looksLikeNegativeNumber(text) {
  if (text.length < 2 || text[0] !== '-') return false;
  const rest = text.slice(1);
  if (isDigits(rest)) return true;
  const dot = rest.indexOf('.');
  if (dot === -1) return false;
  const intPart = rest.slice(0, dot);
  const fracPart = rest.slice(dot + 1);
  return isDigits(intPart) && fracPart.length > 0 && isDigits(fracPart);
}

// Mirrors argparse._parse_optional: decides whether a token is option-like
// (this parser has no options that look like negative numbers, and tokens
// containing a space are never treated as option strings).
function looksLikeOptionString(token) {
  if (token.length < 2 || token[0] !== '-') return false;
  if (looksLikeNegativeNumber(token)) return false;
  if (token.includes(' ')) return false;
  return true;
}

export function formatUsage(prog) {
  return 'usage: ' + prog + ' [-h] --a A\n';
}

export function formatHelp(prog) {
  return (
    formatUsage(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n'
  );
}

// Resolves a long-option name (possibly abbreviated) to its full form.
// Returns { option } on success, { ambiguous: [...] } or null when unknown.
function resolveLongOption(name) {
  if (LONG_OPTIONS.includes(name)) return { option: name };
  const matches = [];
  for (const candidate of LONG_OPTIONS) {
    if (candidate.startsWith(name)) matches.push(candidate);
  }
  if (matches.length === 1) return { option: matches[0] };
  if (matches.length > 1) return { ambiguous: matches };
  return null;
}

// Parses argv (arguments after the program name) for prog.
// Returns one of:
//   { kind: 'ok', args: { a: string } }
//   { kind: 'help', text }                  — full help text for stdout, exit 0
//   { kind: 'error', message, text }        — full usage+error for stderr, exit 2
export function parseArgs(argv, prog) {
  const fail = (message) => ({
    kind: 'error',
    message,
    text: formatUsage(prog) + prog + ': error: ' + message + '\n',
  });

  let aSeen = false;
  let aValue = null;
  const extras = [];
  let positionalOnly = false;
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];
    i += 1;

    if (positionalOnly) {
      extras.push(token);
      continue;
    }

    // The first '--' ends option processing and is itself discarded.
    if (token === '--') {
      positionalOnly = true;
      continue;
    }

    if (!looksLikeOptionString(token)) {
      extras.push(token);
      continue;
    }

    let option = null;
    let explicit = null;

    if (token.startsWith('--')) {
      let name = token;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        explicit = token.slice(eq + 1);
      }
      const resolved = resolveLongOption(name);
      if (resolved === null) {
        extras.push(token);
        continue;
      }
      if (resolved.ambiguous) {
        return fail('ambiguous option: ' + name + ' could match ' + resolved.ambiguous.join(', '));
      }
      option = resolved.option;
    } else if (token === '-h') {
      option = '--help';
    } else if (token.startsWith('-h')) {
      // Short-option prefix: '-hx' / '-h=x' give -h an explicit argument.
      option = '--help';
      explicit = token.slice(2);
      if (explicit.startsWith('=')) explicit = explicit.slice(1);
    } else {
      extras.push(token);
      continue;
    }

    if (option === '--help') {
      if (explicit !== null) {
        return fail("argument -h/--help: ignored explicit argument '" + explicit + "'");
      }
      return { kind: 'help', text: formatHelp(prog) };
    }

    // option === '--a' (nargs=None: exactly one argument).
    if (explicit !== null) {
      aValue = explicit;
      aSeen = true;
      continue;
    }
