  if (!aSeen) {
    return fail('the following arguments are required: --a');
  }
  if (extras.length > 0) {
    return fail('unrecognized arguments: ' + extras.join(' '));
  }
  return { kind: 'ok', args: { a: aValue } };
}

// test2.mjs — Node port of: parse `--a`, evaluate it as a Python expression,
// then print(yaml.dump(eval(args.a))). Pure Node ESM, local imports only.
//
// Exit behavior mirrors the original:
//   -h/--help      -> help text on stdout, exit 0
//   argparse error -> usage + error on stderr, exit 2
//   eval/dump error -> message on stderr, exit 1
//   success        -> dumpYaml output plus print's extra newline on stdout, exit 0

import { basename } from 'node:path';
import { parseArgs } from './argparse.mjs';
import { parsePythonExpression } from './pyparser.mjs';
import { dumpYaml } from './yamldump.mjs';

function main() {
  const prog = basename(process.argv[1] || 'test2.mjs');
  const parsed = parseArgs(process.argv.slice(2), prog);

  if (parsed.kind === 'help') {
    process.stdout.write(parsed.text);
    return 0;
  }
  if (parsed.kind === 'error') {
    process.stderr.write(parsed.text);
    return 2;
  }

  let dumped;
  try {
    const value = parsePythonExpression(parsed.args.a);
    dumped = dumpYaml(value);
  } catch (error) {
    const message = error && error.message ? error.message : String(error);
    process.stderr.write(prog + ': error: ' + message + '\n');
    return 1;
  }

  // yaml.dump output already ends with '\n'; print() adds one more.
  process.stdout.write(dumped);
  process.stdout.write('\n');
  return 0;
}

process.exitCode = main();

